class SimpleHashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [[] for _ in range(size)]

    def _hash(self, key):
        return hash(key) % self.size

    def put(self, key, value):
        bucket = self.table[self._hash(key)]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))

    def get(self, key):
        bucket = self.table[self._hash(key)]
        for k, v in bucket:
            if k == key:
                return v
        raise KeyError(key)

    def delete(self, key):
        bucket = self.table[self._hash(key)]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                del bucket[i]
                return True
        return False

    def keys(self):
        result = []
        for bucket in self.table:
            for k, _ in bucket:
                result.append(k)
        return result


def word_count(sentence):
    ht = SimpleHashTable()
    for word in sentence.lower().split():
        try:
            count = ht.get(word)
            ht.put(word, count + 1)
        except KeyError:
            ht.put(word, 1)
    return ht


result = word_count('the cat sat on the mat the cat')
